typedef long long ll;

static ll maxll(ll a, ll b) { return a > b ? a : b; }

int main(void) {
    int n;
    ll m;
    if (scanf("%d %lld", &n, &m) != 2) return 0;

    ll *a = (ll *)malloc((n + 1) * sizeof(ll));
    ll *b = (ll *)malloc((n + 1) * sizeof(ll));
    ll *d = (ll *)malloc((n + 1) * sizeof(ll));

    for (int i = 1; i <= n; i++) scanf("%lld", &a[i]);
    for (int i = 1; i <= n; i++) scanf("%lld", &b[i]);

    for (int i = 1; i <= n; i++) {
        d[i] = (b[i] - a[i] + m) % m;   // required increments for counter i
    }

    /*
      Each operation adds 1 to a contiguous segment.
      For a linear array, minimum operations to realize nonnegative array d[]
      is:
          d[1] + sum_{i=2..n} max(0, d[i] - d[i-1])
      because every time height increases, new segments must start.
    */

    ll ans = d[1];
    for (int i = 2; i <= n; i++) {
        if (d[i] > d[i - 1]) ans += d[i] - d[i - 1];
    }

    printf("%lld\n", ans);

    free(a);
    free(b);
    free(d);
    return 0;
}

import java.util.Scanner;

public class TallyCounters {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int maxVal = sc.nextInt();
        int[] initial = new int[n];
        int[] target = new int[n];

        for (int i = 0; i < n; i++) {
            initial[i] = sc.nextInt();
        }
        for (int i = 0; i < n; i++) {
            target[i] = sc.nextInt();
        }

        int[] diff = new int[n];
        for (int i = 0; i < n; i++) {
            diff[i] = (target[i] - initial[i] + maxVal) % maxVal;
        }

        int operations = 0;
        for (int i = 0; i < n; i++) {
            if (diff[i] > 0) {
                operations++;
                int j = i;
                while (j < n && diff[j] > 0) {
                    diff[j]--;
                    j++;
                }
                i--; // recheck current position after decrement
            }
        }

        System.out.println(operations);
        sc.close();
    }
}

