import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();

        long[] need = new long[n];
        for (int i = 0; i < n; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            need[i] = (b - a + m) % m;
        }

        long ans = need[0];
        for (int i = 1; i < n; i++) {
            if (need[i] > need[i - 1]) ans += need[i] - need[i - 1];
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

def solve():
    import sys
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    n, m = int(input_data[0]), int(input_data[1])
    current = list(map(int, input_data[2:2+n]))
    target = list(map(int, input_data[2+n:2+2*n]))

    ops = 0
    prev = 0
    for i in range(n):
        # needed increase from current to target
        if target[i] >= current[i]:
            need = target[i] - current[i]
        else:
            need = m - current[i] + target[i]
        if need > prev:
            ops += need - prev
        prev = need
    print(ops)

if __name__ == "__main__":
    solve()

