int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<long long> a(n), b(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) cin >> b[i];

    // Needed increments for each counter modulo m:
    // values are from 1..m, and after m comes 1.
    vector<long long> d(n);
    for (int i = 0; i < n; ++i) {
        d[i] = (b[i] - a[i] + m) % m;
    }

    // Minimum number of operations for raising adjacent segments
    // equals:
    // d[0] + sum(max(0, d[i] - d[i-1])).
    long long ans = d[0];
    for (int i = 1; i < n; ++i) {
        if (d[i] > d[i - 1]) ans += d[i] - d[i - 1];
    }

    cout << ans << '\n';
    return 0;
}
